SELECT jsonb_agg(to_jsonb(t))::text AS fingerprints FROM (SELECT 'Loans' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Borrowers',nullif(c."Ref Borrowers",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Loans" c UNION ALL SELECT 'Repayments' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Loans',nullif(c."Ref Loans",''),'Ref Charges',nullif(c."Ref Charges",''),'Ref Payment',nullif(c."Ref Payment",''),'Ref Payment Allocation',nullif(c."Ref Payment Allocation",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Repayments" c UNION ALL SELECT 'Charges' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Loans',nullif(c."Ref Loans",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Charges" c UNION ALL SELECT 'Loan Assessment' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Borrower',nullif(c."Ref Borrower",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Loan Assessment" c UNION ALL SELECT 'Cash Pool Contributions' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Partner',nullif(c."Ref Partner",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Cash Pool Contributions" c UNION ALL SELECT 'Settlements' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Partner',nullif(c."Ref Partner",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Settlements" c UNION ALL SELECT 'Payment Allocations' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Payment',nullif(c."Ref Payment",''),'Ref Charge',nullif(c."Ref Charge",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Payment Allocations" c UNION ALL SELECT 'Payments' AS table_name,count(*) AS rows,md5(coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('Ref Borrower',nullif(c."Ref Borrower",''),'Ref Target Charge',nullif(c."Ref Target Charge",'')) ORDER BY c."Row ID")::text,'')) AS normalized_hash FROM public."Payments" c) t;